/**
 * Optional written feedback, generated by the server from the measured
 * numbers only. If the AI service isn't configured or fails, we say so and
 * show nothing else: the measurements above stand on their own.
 */
import React, { useState } from 'react';
import type { TakeMeasurements } from '../../analysis/summary';

export function feedbackPayload(m: TakeMeasurements, raagName: string) {
  return {
    raagName,
    saHz: Number(m.saHz.toFixed(2)),
    saSource: m.saSource,
    durationSec: Number(m.durationSec.toFixed(1)),
    singingSec: Number(m.voicedSec.toFixed(1)),
    heldSec: Number(m.heldSec.toFixed(1)),
    heldWithin20CentsPct: m.heldWithin20CentsPct === null ? null : Number(m.heldWithin20CentsPct.toFixed(1)),
    medianAbsDeviationCents: m.medianAbsDeviationCents === null ? null : Number(m.medianAbsDeviationCents.toFixed(1)),
    longestPhraseSec: m.longestPhraseSec === null ? null : Number(m.longestPhraseSec.toFixed(1)),
    medianPhraseSec: m.medianPhraseSec === null ? null : Number(m.medianPhraseSec.toFixed(1)),
    lowestNote: m.lowestNote?.label ?? null,
    highestNote: m.highestNote?.label ?? null,
    ruleFlags: m.ruleFlags.map(f => ({ atSec: Number(f.atSec.toFixed(1)), swara: `${f.label} (${f.name})`, heldSec: Number(f.durSec.toFixed(1)) })),
    oscillations: m.oscillations.map(o => ({ atSec: Number(o.startSec.toFixed(1)), around: o.centreLabel, rateHz: Number(o.rateHz.toFixed(1)), widthCents: Math.round(o.widthCents) })),
    swaras: m.swaras.map(s => ({
      swara: `${s.symbol} (${s.name})`,
      inRaag: s.inRaag,
      timesHeld: s.heldNotes,
      totalHeldSec: Number(s.totalHeldSec.toFixed(1)),
      longestHoldSec: Number(s.longestHoldSec.toFixed(1)),
      medianPositionCents: Number(s.medianDeviationCents.toFixed(1)),
      wobbleCents: Number(s.medianWobbleCents.toFixed(1)),
    })),
  };
}

export const FeedbackPanel: React.FC<{ m: TakeMeasurements; raagName: string }> = ({ m, raagName }) => {
  const [state, setState] = useState<"idle" | "loading" | "done" | "unavailable" | "error">("idle");
  const [text, setText] = useState("");
  const [reason, setReason] = useState("");

  const request = async () => {
    setState("loading");
    try {
      const res = await fetch("/api/feedback", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ measurements: feedbackPayload(m, raagName) }),
      });
      const data = await res.json();
      if (data.unavailable) { setReason(data.reason || ""); setState("unavailable"); return; }
      if (!res.ok || !data.text) throw new Error(data.error || "No feedback returned");
      setText(data.text);
      setState("done");
    } catch (e: any) {
      setReason(e?.message || "");
      setState("error");
    }
  };

  return (
    <div className="bg-[#151A2E] p-5 rounded-2xl border border-slate-800 space-y-3">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
        <div>
          <h3 className="text-xs font-mono font-bold text-slate-300 uppercase tracking-widest">Written feedback (optional)</h3>
          <p className="text-[11px] text-slate-500">
            An AI model reads only the measurements above and comments through different gharana-style lenses.
            It is a study aid, not a guru, and it is told never to invent numbers.
          </p>
        </div>
        {state !== "done" && (
          <button
            type="button"
            onClick={request}
            disabled={state === "loading"}
            className="px-4 py-2 rounded-lg bg-[#7C3AED] hover:bg-[#6D28D9] disabled:opacity-60 text-white text-xs font-mono font-bold cursor-pointer shrink-0"
          >
            {state === "loading" ? "Writing..." : "Get feedback"}
          </button>
        )}
      </div>
      {state === "unavailable" && (
        <p className="text-xs text-slate-400">Written feedback isn't set up on this server{reason ? ` (${reason})` : ""}. The measurements above are complete without it.</p>
      )}
      {state === "error" && (
        <p className="text-xs text-rose-300">Couldn't get feedback right now{reason ? `: ${reason}` : ""}. The measurements above are unaffected.</p>
      )}
      {state === "done" && (
        <div className="text-sm text-slate-300 leading-relaxed space-y-2 whitespace-pre-wrap">{text}</div>
      )}
    </div>
  );
};
